  const prCss = read("static/css/style.css");
  check("pinned region css: .tab-pinned .tab declares flex: 0 0 auto",
    /\.tab-pinned\s+\.tab\s*\{[^}]*flex:\s*0\s+0\s+auto/.test(prCss),
    "no flex:0 0 auto on .tab-pinned .tab");

